CREATE TABLE IF NOT EXISTS "merchants" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Externally quotable account id returned on every API object. Never reused, even after an account is closed.
	"account_reference" VARCHAR(32) NOT NULL UNIQUE,
	-- Business name used on the statement descriptor and in the dashboard.
	"display_name" VARCHAR(160) NOT NULL,
	-- ISO 3166-1 alpha-2. Determines which acquirer, payout rails and dispute rules apply.
	"country_code" CHAR(2) NOT NULL,
	-- ISO 4217 currency the balance settles in. Charges in other currencies convert before payout.
	"default_currency" CHAR(3) NOT NULL,
	-- False until identity verification completes. Payment intents are rejected while it is false, so it is a hard gate rather than a dashboard hint.
	"charges_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- Independent of charges_enabled: an account under review can keep accepting money while payouts stay frozen.
	"payouts_enabled" BOOLEAN NOT NULL DEFAULT false,
	-- manual | daily | weekly | monthly.
	"payout_schedule" VARCHAR(16) NOT NULL DEFAULT 'daily',
	-- How long a charge sits in the pending balance before it becomes payable. This delay is what absorbs the dispute-heavy first days after a sale.
	"payout_delay_days" SMALLINT NOT NULL DEFAULT 2,
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "merchants" IS 'The platform user that money belongs to. Every other table in this schema is scoped to a merchant, because two merchants must never be able to read or settle each other rows.';
COMMENT ON COLUMN "merchants"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "merchants"."account_reference" IS 'Externally quotable account id returned on every API object. Never reused, even after an account is closed.';
COMMENT ON COLUMN "merchants"."display_name" IS 'Business name used on the statement descriptor and in the dashboard.';
COMMENT ON COLUMN "merchants"."country_code" IS 'ISO 3166-1 alpha-2. Determines which acquirer, payout rails and dispute rules apply.';
COMMENT ON COLUMN "merchants"."default_currency" IS 'ISO 4217 currency the balance settles in. Charges in other currencies convert before payout.';
COMMENT ON COLUMN "merchants"."charges_enabled" IS 'False until identity verification completes. Payment intents are rejected while it is false, so it is a hard gate rather than a dashboard hint.';
COMMENT ON COLUMN "merchants"."payouts_enabled" IS 'Independent of charges_enabled: an account under review can keep accepting money while payouts stay frozen.';
COMMENT ON COLUMN "merchants"."payout_schedule" IS 'manual | daily | weekly | monthly.';
COMMENT ON COLUMN "merchants"."payout_delay_days" IS 'How long a charge sits in the pending balance before it becomes payable. This delay is what absorbs the dispute-heavy first days after a sale.';
COMMENT ON COLUMN "merchants"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "customers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning merchant. The same shopper at two merchants is two rows: each merchant holds its own consent and its own token vault.
	"merchant_id" BIGINT NOT NULL,
	-- Public customer id used in API calls and webhook payloads.
	"customer_reference" VARCHAR(32) NOT NULL UNIQUE,
	-- Receipt address. Nullable because a guest checkout can create a customer with nothing but a card.
	"email" VARCHAR(320),
	-- Billing name as entered, not as verified.
	"name" VARCHAR(200),
	-- Preferred instrument for off-session charges. Nullable, and deliberately not a required column, because a customer can exist before any card is attached.
	"default_payment_method_id" BIGINT,
	-- Separates test data from real money inside one database. Every query that touches funds filters on it.
	"livemode" BOOLEAN NOT NULL DEFAULT false,
	-- Merchant-defined key/value pairs echoed back on every object. Opaque to the platform.
	"metadata" JSONB,
	-- First time this shopper was seen.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Soft delete. Charges must keep resolving to a customer long after the merchant removes them from the dashboard.
	"deleted_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "customers" IS 'A shopper as one merchant knows them. Soft-deleted rather than removed, because deleting a customer would orphan years of settled charges and dispute history.';
COMMENT ON COLUMN "customers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "customers"."merchant_id" IS 'Owning merchant. The same shopper at two merchants is two rows: each merchant holds its own consent and its own token vault.';
COMMENT ON COLUMN "customers"."customer_reference" IS 'Public customer id used in API calls and webhook payloads.';
COMMENT ON COLUMN "customers"."email" IS 'Receipt address. Nullable because a guest checkout can create a customer with nothing but a card.';
COMMENT ON COLUMN "customers"."name" IS 'Billing name as entered, not as verified.';
COMMENT ON COLUMN "customers"."default_payment_method_id" IS 'Preferred instrument for off-session charges. Nullable, and deliberately not a required column, because a customer can exist before any card is attached.';
COMMENT ON COLUMN "customers"."livemode" IS 'Separates test data from real money inside one database. Every query that touches funds filters on it.';
COMMENT ON COLUMN "customers"."metadata" IS 'Merchant-defined key/value pairs echoed back on every object. Opaque to the platform.';
COMMENT ON COLUMN "customers"."created_at" IS 'First time this shopper was seen.';
COMMENT ON COLUMN "customers"."deleted_at" IS 'Soft delete. Charges must keep resolving to a customer long after the merchant removes them from the dashboard.';

CREATE INDEX "idx_customers_merchant_email"
ON "customers" ("merchant_id", "email");

CREATE TABLE IF NOT EXISTS "payment_methods" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning merchant.
	"merchant_id" BIGINT NOT NULL,
	-- Attached customer. Null for a one-off method used in a single checkout and never saved.
	"customer_id" BIGINT,
	-- card | bank_account | wallet.
	"method_type" VARCHAR(16) NOT NULL,
	-- visa | mastercard | amex | discover for cards; null for bank debits.
	"brand" VARCHAR(20),
	-- Last four digits, the only part of the instrument safe to display.
	"last_four" CHAR(4),
	-- Card expiry month. Null for non-card methods.
	"exp_month" SMALLINT,
	-- Card expiry year. Null for non-card methods.
	"exp_year" SMALLINT,
	-- Stable hash of the underlying instrument. Lets the platform spot the same card saved twice, or a card banned for fraud, without ever storing the number.
	"fingerprint" VARCHAR(64),
	-- Vault token that stands in for the real credentials. The PAN never enters this database, which is what keeps PCI scope out of it.
	"processor_token" VARCHAR(128) NOT NULL UNIQUE,
	-- Kept for AVS checks at authorization time.
	"billing_postal_code" VARCHAR(16),
	-- active | expired | detached. Detached rows survive so old charges still name the instrument used.
	"status" VARCHAR(16) NOT NULL DEFAULT 'active',
	-- When the method was tokenised.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payment_methods" IS 'A tokenised instrument. Rows are never hard-deleted because a charge from two years ago still has to render as Visa ending 4242.';
COMMENT ON COLUMN "payment_methods"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payment_methods"."merchant_id" IS 'Owning merchant.';
COMMENT ON COLUMN "payment_methods"."customer_id" IS 'Attached customer. Null for a one-off method used in a single checkout and never saved.';
COMMENT ON COLUMN "payment_methods"."method_type" IS 'card | bank_account | wallet.';
COMMENT ON COLUMN "payment_methods"."brand" IS 'visa | mastercard | amex | discover for cards; null for bank debits.';
COMMENT ON COLUMN "payment_methods"."last_four" IS 'Last four digits, the only part of the instrument safe to display.';
COMMENT ON COLUMN "payment_methods"."exp_month" IS 'Card expiry month. Null for non-card methods.';
COMMENT ON COLUMN "payment_methods"."exp_year" IS 'Card expiry year. Null for non-card methods.';
COMMENT ON COLUMN "payment_methods"."fingerprint" IS 'Stable hash of the underlying instrument. Lets the platform spot the same card saved twice, or a card banned for fraud, without ever storing the number.';
COMMENT ON COLUMN "payment_methods"."processor_token" IS 'Vault token that stands in for the real credentials. The PAN never enters this database, which is what keeps PCI scope out of it.';
COMMENT ON COLUMN "payment_methods"."billing_postal_code" IS 'Kept for AVS checks at authorization time.';
COMMENT ON COLUMN "payment_methods"."status" IS 'active | expired | detached. Detached rows survive so old charges still name the instrument used.';
COMMENT ON COLUMN "payment_methods"."created_at" IS 'When the method was tokenised.';

CREATE INDEX "idx_payment_methods_customer_status"
ON "payment_methods" ("customer_id", "status");
CREATE INDEX "idx_payment_methods_fingerprint"
ON "payment_methods" ("merchant_id", "fingerprint");

CREATE TABLE IF NOT EXISTS "payment_intents" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning merchant.
	"merchant_id" BIGINT NOT NULL,
	-- Shopper, when known. Null for anonymous checkouts.
	"customer_id" BIGINT,
	-- Instrument selected so far. Null until the customer picks one, which is exactly why the intent starts in requires_payment_method.
	"payment_method_id" BIGINT,
	-- Public intent id. Safe to embed in a client-side confirmation call.
	"intent_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- Amount to collect, in minor units. Integer only: a cent that rounds is a cent that never reconciles.
	"amount_minor" BIGINT NOT NULL,
	-- Sum captured so far. Lags amount_minor for partial captures and stays zero for a failed intent.
	"amount_received_minor" BIGINT NOT NULL DEFAULT 0,
	-- ISO 4217. Fixed at creation; changing it means a new intent.
	"currency_code" CHAR(3) NOT NULL,
	-- requires_payment_method | requires_confirmation | requires_action | processing | succeeded | canceled. The state machine only moves forward; a failure drops back to requires_payment_method for a retry.
	"status" VARCHAR(32) NOT NULL DEFAULT 'requires_payment_method',
	-- automatic | manual. Manual authorises now and captures later, which is how marketplaces hold funds until fulfilment.
	"capture_method" VARCHAR(12) NOT NULL DEFAULT 'automatic',
	-- automatic | manual. Decides whether the server or the client drives the next step.
	"confirmation_method" VARCHAR(12) NOT NULL DEFAULT 'automatic',
	-- redirect_to_url | use_sdk | verify_microdeposits. Set while the customer must complete a 3-D Secure or bank step; null the rest of the time.
	"next_action" VARCHAR(32),
	-- Decline code from the most recent failed attempt, kept so a retry can show the shopper why the last one failed.
	"last_error_code" VARCHAR(48),
	-- duplicate | fraudulent | requested_by_customer | abandoned.
	"cancellation_reason" VARCHAR(32),
	-- What the shopper sees on their bank statement. Capped at 22 characters by the networks.
	"statement_descriptor" VARCHAR(22),
	-- Merchant-defined context, typically the order id in their own system.
	"metadata" JSONB,
	-- Intent creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the intent was abandoned or cancelled.
	"canceled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payment_intents" IS 'One intent per thing the shopper is trying to buy, holding the whole state machine. It survives multiple failed cards, which is why the retry lives here and each attempt becomes its own charge row.';
COMMENT ON COLUMN "payment_intents"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payment_intents"."merchant_id" IS 'Owning merchant.';
COMMENT ON COLUMN "payment_intents"."customer_id" IS 'Shopper, when known. Null for anonymous checkouts.';
COMMENT ON COLUMN "payment_intents"."payment_method_id" IS 'Instrument selected so far. Null until the customer picks one, which is exactly why the intent starts in requires_payment_method.';
COMMENT ON COLUMN "payment_intents"."intent_reference" IS 'Public intent id. Safe to embed in a client-side confirmation call.';
COMMENT ON COLUMN "payment_intents"."amount_minor" IS 'Amount to collect, in minor units. Integer only: a cent that rounds is a cent that never reconciles.';
COMMENT ON COLUMN "payment_intents"."amount_received_minor" IS 'Sum captured so far. Lags amount_minor for partial captures and stays zero for a failed intent.';
COMMENT ON COLUMN "payment_intents"."currency_code" IS 'ISO 4217. Fixed at creation; changing it means a new intent.';
COMMENT ON COLUMN "payment_intents"."status" IS 'requires_payment_method | requires_confirmation | requires_action | processing | succeeded | canceled. The state machine only moves forward; a failure drops back to requires_payment_method for a retry.';
COMMENT ON COLUMN "payment_intents"."capture_method" IS 'automatic | manual. Manual authorises now and captures later, which is how marketplaces hold funds until fulfilment.';
COMMENT ON COLUMN "payment_intents"."confirmation_method" IS 'automatic | manual. Decides whether the server or the client drives the next step.';
COMMENT ON COLUMN "payment_intents"."next_action" IS 'redirect_to_url | use_sdk | verify_microdeposits. Set while the customer must complete a 3-D Secure or bank step; null the rest of the time.';
COMMENT ON COLUMN "payment_intents"."last_error_code" IS 'Decline code from the most recent failed attempt, kept so a retry can show the shopper why the last one failed.';
COMMENT ON COLUMN "payment_intents"."cancellation_reason" IS 'duplicate | fraudulent | requested_by_customer | abandoned.';
COMMENT ON COLUMN "payment_intents"."statement_descriptor" IS 'What the shopper sees on their bank statement. Capped at 22 characters by the networks.';
COMMENT ON COLUMN "payment_intents"."metadata" IS 'Merchant-defined context, typically the order id in their own system.';
COMMENT ON COLUMN "payment_intents"."created_at" IS 'Intent creation time.';
COMMENT ON COLUMN "payment_intents"."canceled_at" IS 'When the intent was abandoned or cancelled.';

CREATE INDEX "idx_intents_merchant_status"
ON "payment_intents" ("merchant_id", "status");
CREATE INDEX "idx_intents_merchant_created"
ON "payment_intents" ("merchant_id", "created_at");

CREATE TABLE IF NOT EXISTS "charges" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent intent. One intent can own several charges when the shopper retries after a decline.
	"payment_intent_id" BIGINT NOT NULL,
	-- Denormalised from the intent so balance and reporting queries never need the join.
	"merchant_id" BIGINT NOT NULL,
	-- Instrument actually charged. Null only if the method row was purged by a vault migration.
	"payment_method_id" BIGINT,
	-- Public charge id, quoted in receipts and disputes.
	"charge_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- Authorised amount in minor units.
	"amount_minor" BIGINT NOT NULL,
	-- Captured amount. Less than amount_minor for a partial capture, which releases the remainder back to the shopper.
	"amount_captured_minor" BIGINT NOT NULL DEFAULT 0,
	-- Running total of refunds. Maintained by the same transaction that inserts a refund so the cap can be enforced without a scan.
	"amount_refunded_minor" BIGINT NOT NULL DEFAULT 0,
	-- Currency presented to the network.
	"currency_code" CHAR(3) NOT NULL,
	-- pending | succeeded | failed.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- False while funds are only authorised. An uncaptured authorisation expires on its own after a few days.
	"captured" BOOLEAN NOT NULL DEFAULT false,
	-- card_declined | insufficient_funds | expired_card and friends. Null on success.
	"failure_code" VARCHAR(48),
	-- Human-readable decline text from the issuer, shown to the merchant but usually not to the shopper.
	"failure_message" VARCHAR(255),
	-- Acquirer reference. This is the value that matches a line in the daily settlement file back to this row, so reconciliation is impossible without it.
	"network_transaction_id" VARCHAR(64),
	-- Fraud score at authorization time, 0-99. Snapshotted because the model changes and the decision must stay explainable.
	"risk_score" SMALLINT,
	-- When an uncaptured authorization lapses.
	"authorization_expires_at" TIMESTAMPTZ,
	-- Authorization time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Capture time. Equal to created_at for automatic capture.
	"captured_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "charges" IS 'One row per attempt against the network. Charges are never updated in place beyond their captured and refunded totals, because every later dispute argues about what this row said on the day.';
COMMENT ON COLUMN "charges"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "charges"."payment_intent_id" IS 'Parent intent. One intent can own several charges when the shopper retries after a decline.';
COMMENT ON COLUMN "charges"."merchant_id" IS 'Denormalised from the intent so balance and reporting queries never need the join.';
COMMENT ON COLUMN "charges"."payment_method_id" IS 'Instrument actually charged. Null only if the method row was purged by a vault migration.';
COMMENT ON COLUMN "charges"."charge_reference" IS 'Public charge id, quoted in receipts and disputes.';
COMMENT ON COLUMN "charges"."amount_minor" IS 'Authorised amount in minor units.';
COMMENT ON COLUMN "charges"."amount_captured_minor" IS 'Captured amount. Less than amount_minor for a partial capture, which releases the remainder back to the shopper.';
COMMENT ON COLUMN "charges"."amount_refunded_minor" IS 'Running total of refunds. Maintained by the same transaction that inserts a refund so the cap can be enforced without a scan.';
COMMENT ON COLUMN "charges"."currency_code" IS 'Currency presented to the network.';
COMMENT ON COLUMN "charges"."status" IS 'pending | succeeded | failed.';
COMMENT ON COLUMN "charges"."captured" IS 'False while funds are only authorised. An uncaptured authorisation expires on its own after a few days.';
COMMENT ON COLUMN "charges"."failure_code" IS 'card_declined | insufficient_funds | expired_card and friends. Null on success.';
COMMENT ON COLUMN "charges"."failure_message" IS 'Human-readable decline text from the issuer, shown to the merchant but usually not to the shopper.';
COMMENT ON COLUMN "charges"."network_transaction_id" IS 'Acquirer reference. This is the value that matches a line in the daily settlement file back to this row, so reconciliation is impossible without it.';
COMMENT ON COLUMN "charges"."risk_score" IS 'Fraud score at authorization time, 0-99. Snapshotted because the model changes and the decision must stay explainable.';
COMMENT ON COLUMN "charges"."authorization_expires_at" IS 'When an uncaptured authorization lapses.';
COMMENT ON COLUMN "charges"."created_at" IS 'Authorization time.';
COMMENT ON COLUMN "charges"."captured_at" IS 'Capture time. Equal to created_at for automatic capture.';

CREATE INDEX "idx_charges_merchant_created"
ON "charges" ("merchant_id", "created_at");
CREATE INDEX "idx_charges_intent"
ON "charges" ("payment_intent_id");

CREATE TABLE IF NOT EXISTS "refunds" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Charge being refunded.
	"charge_id" BIGINT NOT NULL,
	-- Owning merchant, denormalised for balance queries.
	"merchant_id" BIGINT NOT NULL,
	-- Public refund id.
	"refund_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- Refunded amount in minor units. Several partial refunds can stack, and their sum may never exceed the captured amount.
	"amount_minor" BIGINT NOT NULL,
	-- Always the charge currency; a refund cannot change the currency of the original sale.
	"currency_code" CHAR(3) NOT NULL,
	-- duplicate | fraudulent | requested_by_customer. Drives whether the network fee is returned.
	"reason" VARCHAR(32),
	-- pending | succeeded | failed | canceled. A refund can fail days later if the card is closed.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- lost_or_stolen_card | expired_or_canceled_card | unknown. Set when the issuer rejects the credit.
	"failure_reason" VARCHAR(64),
	-- When the refund was requested.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "refunds" IS 'Refunds are rows, not a flag on the charge. Partial refunds, retries after a failed credit, and the audit question of who refunded what all need the list rather than a single amount.';
COMMENT ON COLUMN "refunds"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "refunds"."charge_id" IS 'Charge being refunded.';
COMMENT ON COLUMN "refunds"."merchant_id" IS 'Owning merchant, denormalised for balance queries.';
COMMENT ON COLUMN "refunds"."refund_reference" IS 'Public refund id.';
COMMENT ON COLUMN "refunds"."amount_minor" IS 'Refunded amount in minor units. Several partial refunds can stack, and their sum may never exceed the captured amount.';
COMMENT ON COLUMN "refunds"."currency_code" IS 'Always the charge currency; a refund cannot change the currency of the original sale.';
COMMENT ON COLUMN "refunds"."reason" IS 'duplicate | fraudulent | requested_by_customer. Drives whether the network fee is returned.';
COMMENT ON COLUMN "refunds"."status" IS 'pending | succeeded | failed | canceled. A refund can fail days later if the card is closed.';
COMMENT ON COLUMN "refunds"."failure_reason" IS 'lost_or_stolen_card | expired_or_canceled_card | unknown. Set when the issuer rejects the credit.';
COMMENT ON COLUMN "refunds"."created_at" IS 'When the refund was requested.';

CREATE INDEX "idx_refunds_charge"
ON "refunds" ("charge_id");

CREATE TABLE IF NOT EXISTS "disputes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Charge the cardholder is contesting.
	"charge_id" BIGINT NOT NULL,
	-- Merchant who has to respond.
	"merchant_id" BIGINT NOT NULL,
	-- Public dispute id, also the case number quoted to the network.
	"dispute_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- Disputed amount. Can be less than the charge when the cardholder contests part of an order.
	"amount_minor" BIGINT NOT NULL,
	-- Currency of the dispute, matching the charge.
	"currency_code" CHAR(3) NOT NULL,
	-- fraudulent | product_not_received | product_unacceptable | duplicate | subscription_canceled | credit_not_processed.
	"reason" VARCHAR(40) NOT NULL,
	-- warning_needs_response | needs_response | under_review | won | lost | charge_refunded.
	"status" VARCHAR(32) NOT NULL DEFAULT 'needs_response',
	-- Hard deadline set by the card network. Missing it loses the case automatically, so it is stored rather than derived: the window depends on network, reason and region and cannot be recomputed later.
	"evidence_due_by" TIMESTAMPTZ NOT NULL,
	-- When the merchant filed. Null means the clock is still running.
	"evidence_submitted_at" TIMESTAMPTZ,
	-- Receipts, shipping proof, customer correspondence and service dates, as file references plus free text. Schemaless because every reason code asks for a different bundle.
	"evidence" JSONB,
	-- Whether the merchant can still end it by refunding instead of fighting. Goes false once the network takes the funds back.
	"is_charge_refundable" BOOLEAN NOT NULL DEFAULT false,
	-- When the network notified the platform.
	"opened_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the case closed, won or lost.
	"resolved_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "disputes" IS 'A chargeback case with a countdown attached. The deadline column is the reason this is not just a charge status: the whole operational job is finding the rows whose evidence_due_by is close and whose evidence_submitted_at is still null.';
COMMENT ON COLUMN "disputes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "disputes"."charge_id" IS 'Charge the cardholder is contesting.';
COMMENT ON COLUMN "disputes"."merchant_id" IS 'Merchant who has to respond.';
COMMENT ON COLUMN "disputes"."dispute_reference" IS 'Public dispute id, also the case number quoted to the network.';
COMMENT ON COLUMN "disputes"."amount_minor" IS 'Disputed amount. Can be less than the charge when the cardholder contests part of an order.';
COMMENT ON COLUMN "disputes"."currency_code" IS 'Currency of the dispute, matching the charge.';
COMMENT ON COLUMN "disputes"."reason" IS 'fraudulent | product_not_received | product_unacceptable | duplicate | subscription_canceled | credit_not_processed.';
COMMENT ON COLUMN "disputes"."status" IS 'warning_needs_response | needs_response | under_review | won | lost | charge_refunded.';
COMMENT ON COLUMN "disputes"."evidence_due_by" IS 'Hard deadline set by the card network. Missing it loses the case automatically, so it is stored rather than derived: the window depends on network, reason and region and cannot be recomputed later.';
COMMENT ON COLUMN "disputes"."evidence_submitted_at" IS 'When the merchant filed. Null means the clock is still running.';
COMMENT ON COLUMN "disputes"."evidence" IS 'Receipts, shipping proof, customer correspondence and service dates, as file references plus free text. Schemaless because every reason code asks for a different bundle.';
COMMENT ON COLUMN "disputes"."is_charge_refundable" IS 'Whether the merchant can still end it by refunding instead of fighting. Goes false once the network takes the funds back.';
COMMENT ON COLUMN "disputes"."opened_at" IS 'When the network notified the platform.';
COMMENT ON COLUMN "disputes"."resolved_at" IS 'When the case closed, won or lost.';

CREATE INDEX "idx_disputes_merchant_status"
ON "disputes" ("merchant_id", "status");
CREATE INDEX "idx_disputes_due"
ON "disputes" ("evidence_due_by");

CREATE TABLE IF NOT EXISTS "balance_transactions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Merchant whose balance moves.
	"merchant_id" BIGINT NOT NULL,
	-- charge | refund | dispute | dispute_reversal | payout | fee | adjustment.
	"source_type" VARCHAR(24) NOT NULL,
	-- Set when source_type is charge. Exactly one of the four source columns is non-null.
	"charge_id" BIGINT,
	-- Set when source_type is refund.
	"refund_id" BIGINT,
	-- Set when source_type is dispute or dispute_reversal.
	"dispute_id" BIGINT,
	-- Set when source_type is payout.
	"payout_id" BIGINT,
	-- Signed amount before fees, in minor units. Negative for refunds, disputes and payouts.
	"gross_minor" BIGINT NOT NULL,
	-- Platform and network fee taken from this movement, always positive.
	"fee_minor" BIGINT NOT NULL DEFAULT 0,
	-- gross_minor minus fee_minor. Stored rather than computed so the sum of this column over available rows is literally the payable balance.
	"net_minor" BIGINT NOT NULL,
	-- Currency of the movement. A merchant trading in several currencies has one balance per currency.
	"currency_code" CHAR(3) NOT NULL,
	-- pending | available | paid. Rows become available after the payout delay and paid when a payout sweeps them.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Date the funds become payable, computed once from the payout delay at insert time.
	"available_on" DATE NOT NULL,
	-- When the movement happened.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "balance_transactions" IS 'One journal for everything that moves money on the platform. Sales, refunds, chargebacks, fees and payouts all land here, which is what makes a merchant balance a single sum instead of five queries that have to agree.';
COMMENT ON COLUMN "balance_transactions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "balance_transactions"."merchant_id" IS 'Merchant whose balance moves.';
COMMENT ON COLUMN "balance_transactions"."source_type" IS 'charge | refund | dispute | dispute_reversal | payout | fee | adjustment.';
COMMENT ON COLUMN "balance_transactions"."charge_id" IS 'Set when source_type is charge. Exactly one of the four source columns is non-null.';
COMMENT ON COLUMN "balance_transactions"."refund_id" IS 'Set when source_type is refund.';
COMMENT ON COLUMN "balance_transactions"."dispute_id" IS 'Set when source_type is dispute or dispute_reversal.';
COMMENT ON COLUMN "balance_transactions"."payout_id" IS 'Set when source_type is payout.';
COMMENT ON COLUMN "balance_transactions"."gross_minor" IS 'Signed amount before fees, in minor units. Negative for refunds, disputes and payouts.';
COMMENT ON COLUMN "balance_transactions"."fee_minor" IS 'Platform and network fee taken from this movement, always positive.';
COMMENT ON COLUMN "balance_transactions"."net_minor" IS 'gross_minor minus fee_minor. Stored rather than computed so the sum of this column over available rows is literally the payable balance.';
COMMENT ON COLUMN "balance_transactions"."currency_code" IS 'Currency of the movement. A merchant trading in several currencies has one balance per currency.';
COMMENT ON COLUMN "balance_transactions"."status" IS 'pending | available | paid. Rows become available after the payout delay and paid when a payout sweeps them.';
COMMENT ON COLUMN "balance_transactions"."available_on" IS 'Date the funds become payable, computed once from the payout delay at insert time.';
COMMENT ON COLUMN "balance_transactions"."created_at" IS 'When the movement happened.';

CREATE INDEX "idx_balance_tx_merchant_status"
ON "balance_transactions" ("merchant_id", "currency_code", "status");
CREATE INDEX "idx_balance_tx_available"
ON "balance_transactions" ("merchant_id", "available_on");

CREATE TABLE IF NOT EXISTS "payouts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Merchant being paid.
	"merchant_id" BIGINT NOT NULL,
	-- Public payout id, quoted when a merchant asks where their money is.
	"payout_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- Amount sent, in minor units. Equals the sum of the net_minor of the balance transactions it sweeps.
	"amount_minor" BIGINT NOT NULL,
	-- Payout currency, matching the balance being swept.
	"currency_code" CHAR(3) NOT NULL,
	-- pending | in_transit | paid | failed | canceled. Failure is normal and usually means a closed bank account.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- standard | instant. Instant costs a fee and lands in minutes rather than days.
	"method" VARCHAR(12) NOT NULL DEFAULT 'standard',
	-- Last four of the destination bank account, snapshotted so an old payout still shows where it went after the merchant changes banks.
	"destination_last_four" CHAR(4) NOT NULL,
	-- Expected landing date, which is what support quotes to merchants. Banking days, not calendar days.
	"arrival_date" DATE NOT NULL,
	-- account_closed | invalid_account_number | debit_not_authorized. Null while the payout is healthy.
	"failure_code" VARCHAR(48),
	-- When the payout was created.
	"initiated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the bank confirmed the credit.
	"paid_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "payouts" IS 'A sweep of available balance to the merchant bank account. A failed payout returns its balance transactions to available rather than deleting them, so money is never lost between the two tables.';
COMMENT ON COLUMN "payouts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "payouts"."merchant_id" IS 'Merchant being paid.';
COMMENT ON COLUMN "payouts"."payout_reference" IS 'Public payout id, quoted when a merchant asks where their money is.';
COMMENT ON COLUMN "payouts"."amount_minor" IS 'Amount sent, in minor units. Equals the sum of the net_minor of the balance transactions it sweeps.';
COMMENT ON COLUMN "payouts"."currency_code" IS 'Payout currency, matching the balance being swept.';
COMMENT ON COLUMN "payouts"."status" IS 'pending | in_transit | paid | failed | canceled. Failure is normal and usually means a closed bank account.';
COMMENT ON COLUMN "payouts"."method" IS 'standard | instant. Instant costs a fee and lands in minutes rather than days.';
COMMENT ON COLUMN "payouts"."destination_last_four" IS 'Last four of the destination bank account, snapshotted so an old payout still shows where it went after the merchant changes banks.';
COMMENT ON COLUMN "payouts"."arrival_date" IS 'Expected landing date, which is what support quotes to merchants. Banking days, not calendar days.';
COMMENT ON COLUMN "payouts"."failure_code" IS 'account_closed | invalid_account_number | debit_not_authorized. Null while the payout is healthy.';
COMMENT ON COLUMN "payouts"."initiated_at" IS 'When the payout was created.';
COMMENT ON COLUMN "payouts"."paid_at" IS 'When the bank confirmed the credit.';

CREATE INDEX "idx_payouts_merchant_status"
ON "payouts" ("merchant_id", "status");

CREATE TABLE IF NOT EXISTS "webhook_endpoints" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning merchant. One merchant commonly has several endpoints for different environments.
	"merchant_id" BIGINT NOT NULL,
	-- HTTPS destination. Stored per endpoint rather than per merchant because staging and production listen separately.
	"url" VARCHAR(512) NOT NULL,
	-- Shared secret for the HMAC signature on every delivery, so the receiver can prove the call came from the platform.
	"signing_secret" VARCHAR(128) NOT NULL,
	-- Array of event types this endpoint wants, or a wildcard. Filtering at fan-out time is far cheaper than delivering everything.
	"enabled_events" JSONB NOT NULL,
	-- enabled | disabled. Disabled endpoints are skipped without erroring.
	"status" VARCHAR(16) NOT NULL DEFAULT 'enabled',
	-- Payload version this endpoint was built against. Pinning it is what lets the platform change payload shapes without breaking old integrations.
	"api_version" VARCHAR(16) NOT NULL,
	-- Failure streak. The endpoint is disabled automatically once it gets long enough, which stops a dead URL from consuming the delivery queue forever.
	"consecutive_failures" INTEGER NOT NULL DEFAULT 0,
	-- Registration time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the endpoint was switched off, manually or by the failure streak.
	"disabled_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "webhook_endpoints" IS 'Where events are sent. Keeping the secret and the pinned API version on the endpoint rather than on the merchant is what makes a zero-downtime integration upgrade possible.';
COMMENT ON COLUMN "webhook_endpoints"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "webhook_endpoints"."merchant_id" IS 'Owning merchant. One merchant commonly has several endpoints for different environments.';
COMMENT ON COLUMN "webhook_endpoints"."url" IS 'HTTPS destination. Stored per endpoint rather than per merchant because staging and production listen separately.';
COMMENT ON COLUMN "webhook_endpoints"."signing_secret" IS 'Shared secret for the HMAC signature on every delivery, so the receiver can prove the call came from the platform.';
COMMENT ON COLUMN "webhook_endpoints"."enabled_events" IS 'Array of event types this endpoint wants, or a wildcard. Filtering at fan-out time is far cheaper than delivering everything.';
COMMENT ON COLUMN "webhook_endpoints"."status" IS 'enabled | disabled. Disabled endpoints are skipped without erroring.';
COMMENT ON COLUMN "webhook_endpoints"."api_version" IS 'Payload version this endpoint was built against. Pinning it is what lets the platform change payload shapes without breaking old integrations.';
COMMENT ON COLUMN "webhook_endpoints"."consecutive_failures" IS 'Failure streak. The endpoint is disabled automatically once it gets long enough, which stops a dead URL from consuming the delivery queue forever.';
COMMENT ON COLUMN "webhook_endpoints"."created_at" IS 'Registration time.';
COMMENT ON COLUMN "webhook_endpoints"."disabled_at" IS 'When the endpoint was switched off, manually or by the failure streak.';

CREATE TABLE IF NOT EXISTS "webhook_events" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Merchant the event concerns.
	"merchant_id" BIGINT NOT NULL,
	-- Public event id. Receivers store it to deduplicate, because at-least-once delivery guarantees repeats.
	"event_reference" VARCHAR(40) NOT NULL UNIQUE,
	-- payment_intent.succeeded | charge.refunded | payout.paid and so on. Dotted object.verb, which makes prefix filtering easy.
	"event_type" VARCHAR(64) NOT NULL,
	-- Payload version the body was rendered in.
	"api_version" VARCHAR(16) NOT NULL,
	-- payment_intent | charge | refund | dispute | payout.
	"object_type" VARCHAR(32) NOT NULL,
	-- Public id of the object that changed. Plain text rather than a foreign key, because one events table has to cover every object type in the platform.
	"object_id" VARCHAR(64) NOT NULL,
	-- Full object as it looked when the event fired. Rendered once and frozen, so a redelivery three days later replays history instead of showing the current state.
	"payload" JSONB NOT NULL,
	-- Test or live. Test events must never reach a production endpoint.
	"livemode" BOOLEAN NOT NULL DEFAULT false,
	-- When the underlying change happened, which can be earlier than when the event row was written.
	"occurred_at" TIMESTAMPTZ NOT NULL,
	-- Event creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "webhook_events" IS 'An immutable record of something that happened. The event is written in the same transaction as the change it describes, so a crash can never leave a captured charge with no event to announce it.';
COMMENT ON COLUMN "webhook_events"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "webhook_events"."merchant_id" IS 'Merchant the event concerns.';
COMMENT ON COLUMN "webhook_events"."event_reference" IS 'Public event id. Receivers store it to deduplicate, because at-least-once delivery guarantees repeats.';
COMMENT ON COLUMN "webhook_events"."event_type" IS 'payment_intent.succeeded | charge.refunded | payout.paid and so on. Dotted object.verb, which makes prefix filtering easy.';
COMMENT ON COLUMN "webhook_events"."api_version" IS 'Payload version the body was rendered in.';
COMMENT ON COLUMN "webhook_events"."object_type" IS 'payment_intent | charge | refund | dispute | payout.';
COMMENT ON COLUMN "webhook_events"."object_id" IS 'Public id of the object that changed. Plain text rather than a foreign key, because one events table has to cover every object type in the platform.';
COMMENT ON COLUMN "webhook_events"."payload" IS 'Full object as it looked when the event fired. Rendered once and frozen, so a redelivery three days later replays history instead of showing the current state.';
COMMENT ON COLUMN "webhook_events"."livemode" IS 'Test or live. Test events must never reach a production endpoint.';
COMMENT ON COLUMN "webhook_events"."occurred_at" IS 'When the underlying change happened, which can be earlier than when the event row was written.';
COMMENT ON COLUMN "webhook_events"."created_at" IS 'Event creation time.';

CREATE INDEX "idx_events_merchant_type_created"
ON "webhook_events" ("merchant_id", "event_type", "created_at");

CREATE TABLE IF NOT EXISTS "webhook_deliveries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Event being delivered.
	"event_id" BIGINT NOT NULL,
	-- Destination. One event fans out to every matching endpoint, so an event has many deliveries.
	"endpoint_id" BIGINT NOT NULL,
	-- Retry counter, starting at one. Part of the unique key so a retry is a new row rather than an overwrite.
	"attempt_number" SMALLINT NOT NULL DEFAULT 1,
	-- pending | succeeded | failed. Anything other than a 2xx is a failure and schedules the next attempt.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- HTTP status returned. Null on timeout or connection error.
	"response_status" SMALLINT,
	-- First few kilobytes of the response, kept for support to show merchants what their own server said.
	"response_body" TEXT,
	-- Round-trip time, used to spot endpoints that are slow rather than broken.
	"duration_ms" INTEGER,
	-- Transport error, if the request never got a response.
	"error_message" VARCHAR(255),
	-- When the retry is due, following exponential backoff. Null once the delivery succeeded or gave up.
	"next_attempt_at" TIMESTAMPTZ,
	-- When this attempt fired.
	"attempted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "webhook_deliveries" IS 'One row per HTTP attempt. Separating deliveries from events is what makes retries, per-endpoint failure tracking and honest support answers possible; a delivered flag on the event could express none of it.';
COMMENT ON COLUMN "webhook_deliveries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "webhook_deliveries"."event_id" IS 'Event being delivered.';
COMMENT ON COLUMN "webhook_deliveries"."endpoint_id" IS 'Destination. One event fans out to every matching endpoint, so an event has many deliveries.';
COMMENT ON COLUMN "webhook_deliveries"."attempt_number" IS 'Retry counter, starting at one. Part of the unique key so a retry is a new row rather than an overwrite.';
COMMENT ON COLUMN "webhook_deliveries"."status" IS 'pending | succeeded | failed. Anything other than a 2xx is a failure and schedules the next attempt.';
COMMENT ON COLUMN "webhook_deliveries"."response_status" IS 'HTTP status returned. Null on timeout or connection error.';
COMMENT ON COLUMN "webhook_deliveries"."response_body" IS 'First few kilobytes of the response, kept for support to show merchants what their own server said.';
COMMENT ON COLUMN "webhook_deliveries"."duration_ms" IS 'Round-trip time, used to spot endpoints that are slow rather than broken.';
COMMENT ON COLUMN "webhook_deliveries"."error_message" IS 'Transport error, if the request never got a response.';
COMMENT ON COLUMN "webhook_deliveries"."next_attempt_at" IS 'When the retry is due, following exponential backoff. Null once the delivery succeeded or gave up.';
COMMENT ON COLUMN "webhook_deliveries"."attempted_at" IS 'When this attempt fired.';

CREATE UNIQUE INDEX "uq_deliveries_event_endpoint_attempt"
ON "webhook_deliveries" ("event_id", "endpoint_id", "attempt_number");
CREATE INDEX "idx_deliveries_next_attempt"
ON "webhook_deliveries" ("next_attempt_at");

CREATE TABLE IF NOT EXISTS "idempotency_keys" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning merchant. Keys are scoped per merchant so two integrations cannot collide on a key as unimaginative as order-1.
	"merchant_id" BIGINT NOT NULL,
	-- Client-supplied key on a write request. The whole contract of the API rests on this column.
	"idempotency_key" VARCHAR(255) NOT NULL,
	-- POST | DELETE. Only unsafe methods take a key.
	"request_method" VARCHAR(8) NOT NULL,
	-- Endpoint the key was used against, so the same key on a different route is rejected rather than quietly reused.
	"request_path" VARCHAR(255) NOT NULL,
	-- SHA-256 of the request body. A replay with the same key but a different body is a client bug and returns an error instead of a wrong cached response.
	"request_fingerprint" CHAR(64) NOT NULL,
	-- in_progress | completed. A second request arriving while the first is still in_progress is told to retry, which is what stops two concurrent charges.
	"status" VARCHAR(16) NOT NULL DEFAULT 'in_progress',
	-- Status code of the original response, replayed verbatim on a repeat.
	"response_status" SMALLINT,
	-- Original response body, replayed byte for byte so a retried client sees the first answer, not a new one.
	"response_body" JSONB,
	-- payment_intent | refund | payout. What the original request created.
	"resource_type" VARCHAR(32),
	-- Public id of the created object, so a replay can be answered without rebuilding it.
	"resource_id" VARCHAR(64),
	-- When a worker claimed the key. A stale lock is reclaimed after a timeout so a crashed request does not wedge the key forever.
	"locked_at" TIMESTAMPTZ,
	-- First time this key was seen.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the key stops being honoured, typically 24 hours. After this a repeat is treated as a new request, which is why clients must not retry indefinitely.
	"expires_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "idempotency_keys" IS 'The table that makes retrying safe. A network timeout tells a client nothing about whether the charge happened, so the only correct answer is to retry with the same key and have the database, not the caller, decide whether that is a new charge or a replay.';
COMMENT ON COLUMN "idempotency_keys"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "idempotency_keys"."merchant_id" IS 'Owning merchant. Keys are scoped per merchant so two integrations cannot collide on a key as unimaginative as order-1.';
COMMENT ON COLUMN "idempotency_keys"."idempotency_key" IS 'Client-supplied key on a write request. The whole contract of the API rests on this column.';
COMMENT ON COLUMN "idempotency_keys"."request_method" IS 'POST | DELETE. Only unsafe methods take a key.';
COMMENT ON COLUMN "idempotency_keys"."request_path" IS 'Endpoint the key was used against, so the same key on a different route is rejected rather than quietly reused.';
COMMENT ON COLUMN "idempotency_keys"."request_fingerprint" IS 'SHA-256 of the request body. A replay with the same key but a different body is a client bug and returns an error instead of a wrong cached response.';
COMMENT ON COLUMN "idempotency_keys"."status" IS 'in_progress | completed. A second request arriving while the first is still in_progress is told to retry, which is what stops two concurrent charges.';
COMMENT ON COLUMN "idempotency_keys"."response_status" IS 'Status code of the original response, replayed verbatim on a repeat.';
COMMENT ON COLUMN "idempotency_keys"."response_body" IS 'Original response body, replayed byte for byte so a retried client sees the first answer, not a new one.';
COMMENT ON COLUMN "idempotency_keys"."resource_type" IS 'payment_intent | refund | payout. What the original request created.';
COMMENT ON COLUMN "idempotency_keys"."resource_id" IS 'Public id of the created object, so a replay can be answered without rebuilding it.';
COMMENT ON COLUMN "idempotency_keys"."locked_at" IS 'When a worker claimed the key. A stale lock is reclaimed after a timeout so a crashed request does not wedge the key forever.';
COMMENT ON COLUMN "idempotency_keys"."created_at" IS 'First time this key was seen.';
COMMENT ON COLUMN "idempotency_keys"."expires_at" IS 'When the key stops being honoured, typically 24 hours. After this a repeat is treated as a new request, which is why clients must not retry indefinitely.';

CREATE UNIQUE INDEX "uq_idempotency_merchant_key"
ON "idempotency_keys" ("merchant_id", "idempotency_key");
CREATE INDEX "idx_idempotency_expires"
ON "idempotency_keys" ("expires_at");

